(* [comment removed for export] *)
Theorem fc_front : cps asegs (ASTA RTA Σ PMc (eq (core_entry Σ B gp t0 t1 t2 a4 a5 a6 a7 t3 t4 t5 t6 F fc n mX)))
  (fun c => exists P, sgrant_ok Σ P (smsz n) /\ ASTA RTA (saΣ Σ P n) PMc (fA P) c).
Proof using FDO MST Hn Hcr HA MI ST LOW LOR SPT GN.
  eapply (cps_seq asegs); [exact fc_evt|]. eapply (cps_seq asegs); [exact fc_grant|].
  apply (cps_ex asegs). intros P T c (Hg & Hc) Hk.
  apply (fc_allow P Hg T c Hc). intros c' Hc'. apply Hk. exists P. split; [exact Hg | exact Hc'].
Qed.
